-- «دفتر»: العملاء والمنتجات (بدون صور ولا مخزون ولا حركات).
-- آمن للتشغيل أكثر من مرة: كل سجل يُضاف فقط إن لم يكن موجوداً، ولا يُعدَّل أو يُحذف أي شيء.
-- يتطلب وجود حساب المالك أولاً (erp:create-owner). التشغيل:  mysql -u erp -p erp < daftar-customers-products.sql
-- 20 منتج، 20 باركود، 13 عميل.
SET NAMES utf8mb4;
START TRANSACTION;

-- المالك هو من يُسجَّل كمنشئ للسجلات. إن لم يوجد، يتوقف الملف عند أول إدخال ولا يُحفظ شيء.
SET @owner := (SELECT ur.user_id FROM user_roles ur JOIN roles r ON r.id = ur.role_id WHERE r.name = 'owner' ORDER BY ur.user_id LIMIT 1);

